def enrich(page: str) -> str:
    """Preserve edited sections across normal Signals regeneration."""
    if 'id="sxf-hydrogen-model-picker"' in page:
        return page
    for name, anchor in ANCHORS.items():
        if page.count(anchor) != 1:
            raise ValueError(f"Gemini Hydrogen editorial insertion anchor changed: {name}")
        page = page.replace(anchor, MODULES[name] + anchor, 1)
    return page
